"""HazardForge: adversarial landing scenes generated by Muse Image, verified by SAM 3.1.

Loop (one round):
  1. pick a certified zone in a real nadir frame
  2. Muse Image edits a crop around it to insert a hazard ("a person lying on the grass",
     "shallow brown floodwater", "a fallen power cable"...)
  3. SAM 3.1 must find the inserted hazard near the zone centre, and NOT find it in the
     original crop -> otherwise the trap is rejected (no unverified synthetic labels)
  4. every landing strategy is run on the trap frame; a strategy is FOOLED if its pick
     lies within (radius + class buffer) of the inserted hazard
  5. Muse Spark reads the failure table and writes round N+1 (structured JSON)

Trap frames + their SAM masks are also training data for the next student (v2).
"""

from __future__ import annotations

import json
import math
from dataclasses import asdict, dataclass, field
from pathlib import Path

import cv2
import numpy as np

from ..evidence import Instance
from ..meta.sam import Region, SamBackend
from ..vocab import Vocabulary

SEED_TRAPS = [
    {"phrase": "person lying on the ground", "instruction": "a person lying on their back on the ground, arms by their sides, wearing a {color} shirt", "size_m": 1.7},
    {"phrase": "flood water", "instruction": "shallow muddy brown floodwater covering the ground, with ripples and a faint sky reflection, as after heavy monsoon rain", "size_m": 9.0},
    {"phrase": "cow", "instruction": "a white cow standing on the ground", "size_m": 2.2},
    {"phrase": "tarpaulin", "instruction": "a {color} plastic tarpaulin sheet spread flat on the ground", "size_m": 4.0},
    {"phrase": "child", "instruction": "a small child standing on the ground, wearing a {color} t-shirt", "size_m": 0.9},
    {"phrase": "motorcycle", "instruction": "a parked motorcycle", "size_m": 2.0},
    {"phrase": "debris", "instruction": "a scattered pile of broken branches, bricks and plastic debris", "size_m": 3.0},
    {"phrase": "puddle", "instruction": "a large puddle of standing rain water", "size_m": 4.0},
]
COLORS = ["red", "yellow", "blue", "white", "green", "orange", "pink", "black"]

EDIT_TEMPLATE = (
    "Edit this straight-down (nadir) aerial drone photograph. Add {what} at the exact centre of the image. "
    "Seen from directly above, at realistic scale: it should be about {px} pixels across. "
    "Match the existing lighting, shadows, blur and colour grading. Keep every other part of the image unchanged. Photorealistic."
)


@dataclass
class Trap:
    trap_id: str
    phrase: str
    instruction: str
    size_m: float
    round: int = 1
    accepted: bool = False
    reject_reason: str = ""
    center_px: tuple[float, float] | None = None
    frame_path: str | None = None
    mask_bounds: tuple | None = None
    results: dict = field(default_factory=dict)  # strategy -> {"fooled": bool, "pick": [x, y]}


class HazardForge:
    def __init__(self, vocab: Vocabulary, sam: SamBackend, muse_image, out_dir: str | Path, spark=None, context_m: float = 14.0, seed: int = 0):
        self.vocab, self.sam, self.muse, self.spark = vocab, sam, muse_image, spark
        self.out = Path(out_dir)
        (self.out / "frames").mkdir(parents=True, exist_ok=True)
        self.context_m = context_m
        self.rng = np.random.default_rng(seed)

    # ------------------------------------------------------------------ 1-3. make + verify one trap
    def make_trap(self, rgb: np.ndarray, zone_px, gsd: float, spec: dict, trap_id: str, round_: int = 1) -> tuple[Trap, np.ndarray | None, Instance | None]:
        what = spec["instruction"].replace("{color}", str(self.rng.choice(COLORS)))
        trap = Trap(trap_id, spec["phrase"], what, float(spec.get("size_m", 2.0)), round_)
        self.vocab.class_of(trap.phrase)
        h, w = rgb.shape[:2]
        half = int(self.context_m / gsd)
        cx, cy = int(zone_px[0]), int(zone_px[1])
        x0, y0, x1, y1 = max(0, cx - half), max(0, cy - half), min(w, cx + half), min(h, cy + half)
        crop = rgb[y0:y1, x0:x1]
        px = max(4, int(trap.size_m / gsd))
        prompt = EDIT_TEMPLATE.format(what=what, px=px)
        try:
            edited = self.muse.edit([crop], prompt)
        except Exception as e:
            trap.reject_reason = f"muse image error: {e}"
            return trap, None, None
        frame = rgb.copy()
        frame[y0:y1, x0:x1] = _feather_paste(crop, edited)

        # SAM must see the hazard near the centre of the edited frame and not in the original
        region = Region(x0, y0, x1, y1, 1024)
        reach = (trap.size_m / 2 + 3.0) / gsd
        after = [i for i in self.sam.segment(frame, trap.phrase, region) if i.distance_px((cx, cy)) <= reach]
        before = [i for i in self.sam.segment(rgb, trap.phrase, region) if i.distance_px((cx, cy)) <= reach]
        if not after:
            trap.reject_reason = "SAM 3.1 did not find the inserted hazard"
        elif before:
            trap.reject_reason = "hazard already present before the edit"
        else:
            trap.accepted = True
            best = max(after, key=lambda i: i.area_px)
            trap.center_px = (float(cx), float(cy))
            trap.mask_bounds = best.bounds
            fp = self.out / "frames" / f"{trap_id}.png"
            cv2.imwrite(str(fp), cv2.cvtColor(frame, cv2.COLOR_RGB2BGR))
            trap.frame_path = str(fp)
            return trap, frame, best
        return trap, None, None

    # ------------------------------------------------------------------ 4. who gets fooled?
    def evaluate(self, trap: Trap, frame: np.ndarray, hazard: Instance, gsd: float, alt: float, strategies: dict, airframe) -> None:
        """A strategy is fooled if its touchdown disc (+ class buffer) overlaps the inserted hazard."""
        reach = airframe.required_radius_m(alt) + self.vocab.class_of(trap.phrase).buffer_m
        for name, strat in strategies.items():
            pick = strat.pick(frame, gsd, alt, {"trap": trap, "hazard": hazard})
            if pick.xy is None:
                trap.results[name] = {"fooled": False, "pick": None, "abstained": True}
                continue
            d_m = hazard.distance_px(pick.xy) * gsd
            trap.results[name] = {"fooled": bool(d_m < reach), "pick": [round(pick.xy[0], 1), round(pick.xy[1], 1)], "distance_m": round(d_m, 2)}

    # ------------------------------------------------------------------ 5. next round
    def next_round(self, traps: list[Trap], n: int = 8) -> list[dict]:
        table = [{"phrase": t.phrase, "instruction": t.instruction, "size_m": t.size_m, "accepted": t.accepted,
                  "fooled": {k: v["fooled"] for k, v in t.results.items()}} for t in traps]
        if self.spark is not None:
            from ..agents.prompts import FORGE_SYSTEM

            schema = {"type": "object", "properties": {"traps": {"type": "array", "items": {"type": "object", "properties": {
                "phrase": {"type": "string", "enum": self.vocab.hazard_phrases}, "instruction": {"type": "string"},
                "size_m": {"type": "number"}, "rationale": {"type": "string"}}, "required": ["phrase", "instruction", "size_m", "rationale"]}}},
                "required": ["traps"]}
            res = self.spark.json([{"role": "system", "content": FORGE_SYSTEM},
                                   {"role": "user", "content": f"Last round:\n{json.dumps(table, indent=1)}\n\nPropose {n} traps for the next round."}], schema, name="forge_round")
            return res["traps"][:n]
        # deterministic fallback: mutate what fooled anything, then fill from the seed library
        fooled = [t for t in traps if t.accepted and any(v["fooled"] for v in t.results.values())]
        out = [{"phrase": t.phrase, "instruction": t.instruction, "size_m": round(t.size_m * 0.7, 2)} for t in fooled]
        for s in SEED_TRAPS:
            if len(out) >= n:
                break
            out.append(dict(s))
        return out[:n]

    def save(self, traps: list[Trap], name: str = "traps.json") -> Path:
        p = self.out / name
        p.write_text(json.dumps([asdict(t) for t in traps], indent=1, default=str))
        return p


def failure_table(traps: list[Trap]) -> dict:
    acc = [t for t in traps if t.accepted]
    names = sorted({k for t in acc for k in t.results})
    return {
        "generated": len(traps),
        "accepted_by_sam": len(acc),
        "fooled_rate": {n: round(sum(t.results[n]["fooled"] for t in acc if n in t.results) / max(1, sum(n in t.results for t in acc)), 3) for n in names},
    }


def _feather_paste(orig: np.ndarray, edited: np.ndarray, frac: float = 0.08) -> np.ndarray:
    h, w = orig.shape[:2]
    if edited.shape[:2] != (h, w):
        edited = cv2.resize(edited, (w, h), interpolation=cv2.INTER_AREA)
    ramp = max(2, int(min(h, w) * frac))
    a = np.ones((h, w), np.float32)
    for i in range(ramp):
        v = (i + 1) / ramp
        a[i, :] = np.minimum(a[i, :], v)
        a[h - 1 - i, :] = np.minimum(a[h - 1 - i, :], v)
        a[:, i] = np.minimum(a[:, i], v)
        a[:, w - 1 - i] = np.minimum(a[:, w - 1 - i], v)
    return (edited * a[..., None] + orig * (1 - a[..., None])).astype(np.uint8)
